insert into public.survey_versions(tenant_id,survey_id,version,definition,owner_id,state)
select 'e3200000-0000-4000-8000-000000000001',gen_random_uuid(),1,(select v from p14 where k='definition')||jsonb_build_object('title',k,'trigger',k,'audience','VIP'),'e3100000-0000-4000-8000-000000000001','PUBLISHED' from unnest(array['VIP_JOIN','CANCELLATION','DEPARTURE','PERIODIC']) k;
select ok(private.survey_eligibility('e3200000-0000-4000-8000-000000000001',(select id from public.survey_versions where definition->>'title'='VIP_JOIN'),'e3300000-0000-4000-8000-000000000001',((select v from p14 where k='conversation')#>>'{}')::uuid,false)->'blockers' ? 'VERIFIED_JOIN_REQUIRED','a claimed VIP join creates no eligibility');
select ok(private.survey_eligibility('e3200000-0000-4000-8000-000000000001',(select id from public.survey_versions where definition->>'title'='CANCELLATION'),'e3300000-0000-4000-8000-000000000001',((select v from p14 where k='conversation')#>>'{}')::uuid,false)->'blockers' ? 'VERIFIED_CANCELLATION_REQUIRED','cancellation needs trusted current terms');
