select ok(private.survey_eligibility('e3200000-0000-4000-8000-000000000001',(select id from public.survey_versions where definition->>'title'='PERIODIC'),'e3300000-0000-4000-8000-000000000001',((select v from p14 where k='conversation')#>>'{}')::uuid,false)->'blockers' ? 'PERIODIC_DISABLED','periodic cadence defaults disabled');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and (p.proname like 'survey_%' or p.proname like 'admin_survey_%' or p.proname like 'process_survey_%' or p.proname='configure_phase14_sandbox') and has_function_privilege('anon',p.oid,'EXECUTE')),'all new authority denies anonymous direct execution');
