update private.survey_controls set retention_days=null,legal_hold=false;
select is((public.survey_retention('e3200000-0000-4000-8000-000000000001')->>'policy_active')::boolean,false,'retention has no invented production duration');
select is((select count(*) from public.messages where tenant_id='e3200000-0000-4000-8000-000000000001' and direction='outbound'),0::bigint,'zero customer outbound');
select is((select count(*) from public.domain_events where tenant_id='e3200000-0000-4000-8000-000000000001' and event_type='payment.confirmed'),0::bigint,'zero financial authority');
select is((select count(*) from public.channel_access where tenant_id='e3200000-0000-4000-8000-000000000001'),0::bigint,'zero access grants');
select is((select count(*) from public.import_batches where tenant_id='e3200000-0000-4000-8000-000000000001'),0::bigint,'imports remain unused');
-- Construct one immutable TEST payment period solely as a trigger fixture. No provider call.
update public.tenants set slug='phase11-sandbox-p14-triggers' where id='e3200000-0000-4000-8000-000000000001';
set local role authenticated;select set_config('request.jwt.claim.sub','e3100000-0000-4000-8000-000000000001',true);
insert into p14 select 'test_invoice',to_jsonb(public.admin_create_test_payment_invoice('e3200000-0000-4000-8000-000000000001','e3600000-0000-4000-8000-000000000001','telegram_stars','XTR','100','p14-trigger-fixture'));
insert into p14 select 'test_snapshot',to_jsonb(public.admin_simulate_test_payment('e3200000-0000-4000-8000-000000000001',((select v from p14 where k='test_invoice')#>>'{}')::uuid,'settled','p14-trigger-fixture-settle'));
reset role;
select public.payment_record_test_observation('e3200000-0000-4000-8000-000000000001',((select v from p14 where k='test_invoice')#>>'{}')::uuid,((select v from p14 where k='test_snapshot')#>>'{}')::uuid,'test:p14-trigger',repeat('d',64),'reconcile');
set local role authenticated;
insert into p14 select 'test_subscription',to_jsonb(public.admin_create_test_subscription('e3200000-0000-4000-8000-000000000001',((select v from p14 where k='test_invoice')#>>'{}')::uuid));
select public.admin_test_access_setup('e3200000-0000-4000-8000-000000000001','e3300000-0000-4000-8000-000000000001',(select id from public.domain_events where tenant_id='e3200000-0000-4000-8000-000000000001' and customer_id='e3300000-0000-4000-8000-000000000001' and event_type='customer.created' order by id limit 1),'test:140001');
select public.admin_request_entitlement_access('e3200000-0000-4000-8000-000000000001',((select v from p14 where k='test_subscription')#>>'{}')::uuid);
reset role;
update public.channel_access set status='MEMBER',membership_checked_at=now() where tenant_id='e3200000-0000-4000-8000-000000000001' and mode='test';
update public.tenants set slug='phase14-sandbox-pgtap' where id='e3200000-0000-4000-8000-000000000001';
insert into p14 select 'verified_join',private.survey_eligibility('e3200000-0000-4000-8000-000000000001',(select id from public.survey_versions where definition->>'title'='VIP_JOIN'),'e3300000-0000-4000-8000-000000000001',((select v from p14 where k='conversation')#>>'{}')::uuid,false);
select ok((select not (v->'blockers' ? 'VERIFIED_JOIN_REQUIRED') and v->>'mode'='SIMULATED' and not (v->>'invitation_eligible')::boolean from p14 where k='verified_join'),'verified TEST membership supports review evidence, never live authority');
update public.subscriptions set state='CANCELLED',revision=revision+1 where tenant_id='e3200000-0000-4000-8000-000000000001';
select ok(not (private.survey_eligibility('e3200000-0000-4000-8000-000000000001',(select id from public.survey_versions where definition->>'title'='CANCELLATION'),'e3300000-0000-4000-8000-000000000001',((select v from p14 where k='conversation')#>>'{}')::uuid,false)->'blockers' ? 'VERIFIED_CANCELLATION_REQUIRED'),'current cancellation has verified immutable TEST terms');
update public.channel_access set status='REVOKED',membership_checked_at=now() where tenant_id='e3200000-0000-4000-8000-000000000001' and mode='test';
select ok(not (private.survey_eligibility('e3200000-0000-4000-8000-000000000001',(select id from public.survey_versions where definition->>'title'='DEPARTURE'),'e3300000-0000-4000-8000-000000000001',((select v from p14 where k='conversation')#>>'{}')::uuid,false)->'blockers' ? 'VERIFIED_DEPARTURE_REQUIRED'),'verified TEST departure evidence stays separate from live membership');
set local role authenticated;
select public.admin_survey_policy('e3200000-0000-4000-8000-000000000001','{"cadence_days":7,"cadence_approval":"SYNTHETIC approved cadence test"}',2);
reset role;
select ok(not (private.survey_eligibility('e3200000-0000-4000-8000-000000000001',(select id from public.survey_versions where definition->>'title'='PERIODIC'),'e3300000-0000-4000-8000-000000000001',((select v from p14 where k='conversation')#>>'{}')::uuid,false)->'blockers' ? 'PERIODIC_DISABLED'),'only explicitly approved sandbox cadence supports periodic review');
select public.process_survey_due();
select ok(exists(select 1 from public.scheduled_jobs where tenant_id='e3200000-0000-4000-8000-000000000001' and idempotency_key like 'survey.periodic:%'),'approved periodic processing uses bounded existing jobs, not a campaign');
select is((select count(*) from public.messages where tenant_id='e3200000-0000-4000-8000-000000000001' and direction='outbound'),0::bigint,'all trigger fixtures generate zero customer messages');
select is((select count(*) from public.subscriptions where tenant_id='e3200000-0000-4000-8000-000000000001' and mode='live'),0::bigint,'no live subscription from trigger fixtures');
select * from finish();rollback;
